def parser(log: str) -> dict[str, str]:
    # Improved, robust pytest parser
    import re

    results: dict[str, str] = {}

    # Robust pattern:
    # Capture full test identifier up to a known status token.
    # Supports param names with spaces, brackets, etc.
    status_tokens = r"PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS"
    pattern = re.compile(
        rf"^(?P<name>.+?)\s+(?P<status>{status_tokens})\b",
        re.IGNORECASE
    )

    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue

        m = pattern.match(line)
        if not m:
            continue

        name = m.group("name").strip()
        status = m.group("status").upper()

        if status == "PASSED":
            results[name] = "pass"
        elif status == "SKIPPED":
            results[name] = "skip"
        else:
            # FAILED, ERROR, XFAIL, XPASS → fail
            results[name] = "fail"

    return results

def parser(log: str) -> dict[str, str]:
    import json
    from typing import Any, Dict

    def load_json_from_log(text: str) -> Any:
        """
        Try to robustly extract a JSON object from the log text.

        Strategy:
        1. Find the first '{' and try to json.loads from there.
        2. If that fails, try each line that looks like it could be JSON.
        3. As a last resort, return {}.
        """
        first_brace = text.find("{")
        if first_brace != -1:
            candidate = text[first_brace:].strip()
            # Try full tail first
            try:
                return json.loads(candidate)
            except Exception:
                pass

        # Fallback: try per-line JSON
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            if not (line.startswith("{") and line.endswith("}")):
                continue
            try:
                return json.loads(line)
            except Exception:
                continue

        return {}

    def normalize_outcome(outcome: str) -> str:
        o = (outcome or "").strip().lower()
        if o in ("passed", "pass", "success"):
            return "pass"
        if o in ("skipped", "skip", "xskipped", "xfail", "xfailed"):
            # All explicit skips become "skip"; expected failures are usually
            # treated as passes, but here we keep them as fail/skip depending
            # on needs. We'll treat xfail/xpassed as fail to be conservative.
            if o in ("skipped", "skip", "xskipped"):
                return "skip"
            return "fail"
        # Any failure-like state → fail
        if o in (
            "failed",
            "fail",
            "error",
            "xpassed",
            "rerun",
            "flaky",
            "timeout",
        ):
            return "fail"
        # Unknown outcomes -> fail conservatively
        return "fail"

    def walk(obj: Any, results: Dict[str, str]) -> None:
        """
        Recursively walk arbitrary JSON data and collect test outcomes.

        We consider any dict that has both:
          - "nodeid" (str)
          - "outcome" (str)
        as a test result, regardless of where it appears.
        """
        if isinstance(obj, dict):
            nodeid = obj.get("nodeid")
            outcome = obj.get("outcome")
            if isinstance(nodeid, str) and isinstance(outcome, str):
                status = normalize_outcome(outcome)
                # Last-writer-wins if duplicates; this is fine for pytest
                results[nodeid] = status

            # Recurse into all values
            for v in obj.values():
                walk(v, results)

        elif isinstance(obj, list):
            for item in obj:
                walk(item, results)

        # Other types are ignored

    data = load_json_from_log(log)
    results: Dict[str, str] = {}
    walk(data, results)

    # Ensure only the allowed statuses are present
    cleaned: Dict[str, str] = {}
    for k, v in results.items():
        if v not in ("pass", "fail", "skip"):
            cleaned[k] = "fail"
        else:
            cleaned[k] = v

    return cleaned
